contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(true);
        // read current owner
        address before = c.owner();

        // Attempt transferOwnership from this contract (msg.sender == InvMutTest)
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner after
        address after = c.owner();

        // General rule: if this contract was the owner before, the call must succeed and owner becomes newOwner;
        // otherwise the call must revert and owner stays unchanged.
        assert((before == address(this) && !reverted && after == newOwner) || (before != address(this) && reverted && after == before));
    }
    receive() external payable {}
}

