contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address possibleOwner, address newOwner) public payable {
        require(true);
        // Setup: ensure the InvMutTest contract is the owner if requested by calling transferOwnership when possibleOwner equals address(this).
        // We can only call transferOwnership successfully when msg.sender (this contract) is already owner; since freshly deployed C may have owner = address(0), we first try to set owner to address(this) if possibleOwner permits.

        // Read owner before any operations
        address ownerBefore = c.owner();

        // If the contract is the owner already, optionally transfer ownership to possibleOwner so we can exercise both cases.
        // Attempt to make this contract the owner by trying transferOwnership(address(this)) if ownerBefore == possibleOwner; this is a best-effort setup and may revert.
        bool setupReverted;
        try c.transferOwnership(address(this)) {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        // Record owner after setup
        address ownerAfterSetup = c.owner();

        // Now attempt to call owned() which is protected by onlyOwner. It should succeed (not revert) iff msg.sender == current owner (which is address(this)).
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // Read owner after calling owned()
        address ownerFinal = c.owner();

        // General rule: calling owned() does not change owner, and it reverts exactly when the caller is not the owner.
        // msg.sender for calls on c is this contract, so check equivalence between ownerAfterSetup and address(this) and the revert flag, and ensure ownerFinal equals ownerAfterSetup.
        assert(((ownerAfterSetup == address(this)) && !ownedReverted && ownerFinal == ownerAfterSetup) || ((ownerAfterSetup != address(this)) && ownedReverted && ownerFinal == ownerAfterSetup));
    }
    receive() external payable {}
}

